def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    units = supply / float(WATER_REQ)
    severe_tight = units <= 1.25
    tight = units <= 1.6
    roomy = units >= 1.9

    prev_bids = []
    rich_pressure = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) > budget * 0.9:
                if bid > rich_pressure:
                    rich_pressure = float(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    ref_bid = max(highest_prev, rich_pressure)

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if severe_tight:
        urgency += 2
    elif tight:
        urgency += 1
    elif roomy:
        urgency -= 1

    if day >= 8:
        urgency += 1

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if urgency >= 3:
            base = DAILY_SALARY * 0.75
        return float(min(budget, base))

    if urgency <= 0:
        bid = DAILY_SALARY * 0.28 if roomy else DAILY_SALARY * 0.38
    elif urgency == 1:
        bid = max(DAILY_SALARY * 0.52, ref_bid * 0.78)
    elif urgency == 2:
        bid = max(DAILY_SALARY * 0.72, ref_bid + 2.0)
    elif urgency == 3:
        bid = max(DAILY_SALARY * 0.9, ref_bid + 4.0)
    else:
        bid = max(DAILY_SALARY * 1.05, ref_bid + 8.0)

    if roomy and urgency <= 1:
        bid = min(bid, DAILY_SALARY * 0.55)

    if severe_tight and hp <= 4:
        bid = max(bid, ref_bid + 10.0, DAILY_SALARY * 1.0)

    safety_cap = budget
    if hp > 5 and no_water_days == 0 and day < 7:
        safety_cap = min(safety_cap, budget * 0.42 + DAILY_SALARY * 0.25)
    elif hp > 3:
        safety_cap = min(safety_cap, budget * 0.6 + DAILY_SALARY * 0.35)

    bid = min(bid, budget, safety_cap)
    if urgency >= 3:
        bid = min(max(bid, DAILY_SALARY * 0.82), budget)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0.0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opps = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append((oid, o))
        except Exception:
            continue

    # Base conservative bid: enough to compete but not match the top bidders.
    # Scale with supply: higher supply -> lower competitive pressure.
    if supply >= 22:
        base_mult = 0.45
    elif supply >= 18:
        base_mult = 0.55
    else:
        base_mult = 0.65

    # React to yesterday's bidding intensity by alive opponents.
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) if isinstance(o, dict) else {}
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # If someone previously bid very high, we slightly undercut to grab water.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # Thresholds inferred from yesterday: Eric/Alex averaged ~112-123 with max ~226.
        if highest_prev_bid >= 200:
            pressure = 'extreme'
        elif highest_prev_bid >= 120:
            pressure = 'high'
        else:
            pressure = 'medium'
    else:
        pressure = 'low'
        highest_prev_bid = 0.0

    # Determine target bid.
    # If I'm in danger, bid more aggressively.
    if hp <= 2 or no_water_days >= 2:
        danger_mult = 0.85
    elif hp <= 3:
        danger_mult = 0.70
    else:
        danger_mult = 0.60

    if pressure == 'extreme':
        target = min(budget, DAILY_SALARY * 0.75)
        # Undercut the extreme bid if possible.
        target = min(target, highest_prev_bid * 0.92)
    elif pressure == 'high':
        target = min(budget, DAILY_SALARY * 0.65)
        target = min(target, highest_prev_bid * 0.90)
    elif pressure == 'medium':
        target = min(budget, DAILY_SALARY * base_mult * 1.05)
    else:
        target = min(budget, DAILY_SALARY * base_mult)

    # Ensure we don't bid trivially low when supply is low.
    if supply <= 16:
        floor_bid = DAILY_SALARY * 0.55
        if target < floor_bid:
            target = min(budget, floor_bid)

    # If budget is tiny, just spend what we can.
    if budget <= 1:
        return 0.0

    # Keep bid within reasonable bounds.
    if target < 0:
        target = 0.0

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.55 

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 1.3 
    elif my_status['hp'] <= 5:
        base_bid = DAILY_SALARY * 0.95 
    elif my_status['hp'] >= 8 and day_context['day'] < EPISODE_DAYS - 2:
        base_bid = DAILY_SALARY * 0.45 

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid > DAILY_SALARY * 1.2:
            base_bid = max(base_bid, highest_prev_bid * 0.9) 
        elif average_prev_bid > DAILY_SALARY * 0.8:
            base_bid = max(base_bid, average_prev_bid * 0.85) 

        if my_status['hp'] > 5 and highest_prev_bid < DAILY_SALARY * 0.8:
            base_bid = min(base_bid, highest_prev_bid + 5) 

    potential_winners = int(day_context['supply'] / WATER_REQ)

    if potential_winners <= num_alive_opponents:
        if potential_winners == 1 and num_alive_opponents > 0:
            base_bid = max(base_bid, DAILY_SALARY * 1.5) 
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.8) 
            if my_status['hp'] <= 5:
                base_bid = max(base_bid, DAILY_SALARY * 1.1)
    elif potential_winners > num_alive_opponents + 1:
        if my_status['hp'] > 5:
            base_bid = min(base_bid, DAILY_SALARY * 0.4) 
        else:
            base_bid = min(base_bid, DAILY_SALARY * 0.7) 

    final_bid = min(my_status['budget'], base_bid)

    if my_status['budget'] > 0:
        final_bid = max(1.0, final_bid)
    else:
        final_bid = 0.0

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    day = day_context['day']
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive = len(alive_opponents)

    # Estimate how many portions (each 8 units) are available
    max_portions = int(supply // WATER_REQ)  # explicitly convert to int

    # Base bid to aim for a portion
    base_bid = min(my_status['budget'], DAILY_SALARY * 0.8)  # 112
    # Adjust based on number of opponents: more opponents -> higher bid
    if num_alive > 2:
        base_bid = min(my_status['budget'], DAILY_SALARY * 0.85)

    # Day 1: no previous trace, use base
    if day == 1:
        if my_status['hp'] <= 3:
            return min(my_status['budget'], DAILY_SALARY * 0.95)
        if max_portions <= 1:
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        return min(my_status['budget'], base_bid)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        # Fallback
        if my_status['hp'] <= 3:
            return min(my_status['budget'], DAILY_SALARY * 0.95)
        return min(my_status['budget'], base_bid)

    max_prev = max(yesterday_bids)
    avg_prev = sum(yesterday_bids) / len(yesterday_bids)

    # High pressure: if previous high bids, be conservative when HP good
    if max_prev >= DAILY_SALARY * 0.85:
        if my_status['hp'] > 4:
            # Conserve budget
            target = min(my_status['budget'], DAILY_SALARY * 0.35)
        else:
            # Need water
            target = min(my_status['budget'], max(DAILY_SALARY * 0.95, max_prev + 1))
    else:
        # Medium pressure: outbid average slightly
        if my_status['hp'] <= 2:
            target = min(my_status['budget'], max(DAILY_SALARY * 0.9, avg_prev * 1.1))
        else:
            target = min(my_status['budget'], max(DAILY_SALARY * 0.5, avg_prev + 5))

    # Ensure we don't go below 0 or exceed budget
    target = max(0, min(my_status['budget'], target))
    return int(target)  # ensure integer bid
}
